reproduction.command:
bun -e '
import { canonicalSha256, sha256Hex } from "./src/canonical";
import { loadDataset } from "./scripts/benchmarks/io";
import { selectSplit, selectQuestions } from "./scripts/benchmarks/datasets";
import { loadUnitReport } from "./scripts/benchmarks/extract";
import { runRetrieval } from "./scripts/benchmarks/runner";
const sourcePath = ".cache/benchmarks/runs/locomo-memory-strategy-dev-v1.json";
const unitPath = ".cache/benchmarks/runs/locomo-units-development-v1.json";
const sourceBytes = await Bun.file(sourcePath).bytes();
const source = JSON.parse(new TextDecoder().decode(sourceBytes));
const m = source.manifest;
const selected = selectQuestions(selectSplit(await loadDataset(m.dataset), m.split, m.seed), m.limit, m.seed);
if (JSON.stringify(selected.questions.map((q) => q.id)) !== JSON.stringify(m.selectedQuestions)) throw new Error("Question selection changed");
if (JSON.stringify(selected.corpora.map((c) => c.id)) !== JSON.stringify(m.selectedCorpora)) throw new Error("Corpus selection changed");
const memory = await loadUnitReport(unitPath, m.dataset, m.split, m.seed, selected.corpora);
if (memory.provenance.reportSha256 !== source.memoryUnits.reportSha256) throw new Error("Unit report changed");
const replay = await runRetrieval(selected, m.systems, m.budget, m.seed, memory);
const key = (r) => `${r.questionId}:${r.system}`;
const oldByKey = new Map(source.rows.map((r) => [key(r), r]));
const mismatches = replay.rows.filter((r) => { const old = oldByKey.get(key(r)); return !old || old.contextSha256 !== r.contextSha256 || old.contextBytes !== r.contextBytes; });
const contexts = (rows) => rows.map((r) => [key(r), r.contextSha256, r.contextBytes]).sort((a, b) => a[0].localeCompare(b[0]));
const originalContextSetSha256 = canonicalSha256(contexts(source.rows));
const replayContextSetSha256 = canonicalSha256(contexts(replay.rows));
const result = { gitHead: new TextDecoder().decode(Bun.spawnSync(["git", "rev-parse", "HEAD"]).stdout).trim(), bun: Bun.version, sourceReportSha256: sha256Hex(sourceBytes), unitReportSha256: memory.provenance.reportSha256, questions: selected.questions.length, corpora: selected.corpora.length, systems: m.systems, budget: m.budget, originalRows: source.rows.length, replayRows: replay.rows.length, mismatches: mismatches.map((r) => key(r)), originalContextSetSha256, replayContextSetSha256, preparationRecorded: replay.ingestion.every((i) => i.unitIndexes.blocks && i.unitIndexes.facts), status: mismatches.length === 0 && source.rows.length === replay.rows.length && originalContextSetSha256 === replayContextSetSha256 ? "passed" : "failed" };
console.log(JSON.stringify(result, null, 2));
if (result.status !== "passed") process.exit(1);
'
